const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define date
  const date = '2018-02-03';

  // Define country boundaries
  const countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017');
  const vietnam = countries.filter(ee.Filter.eq('country_na', 'Vietnam'));
  const myanmar = countries.filter(ee.Filter.eq('country_na', 'Burma'));

  // Get VIIRS active fire data for the specific date
  const fires = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML')
    .filterDate(date, ee.Date(date).advance(1, 'day'));

  console.log('Collection size:', fires.size().getInfo());

  if (fires.size().getInfo() === 0) {
    console.log('No fire data available for this date.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get the image for the date
  const fireImage = fires.first();

  // Select brightness temperature band (indicator of fire)
  const fireMask = fireImage.select('T13');

  // Count fire detections in Vietnam
  const vietnamStats = fireMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: vietnam.geometry(),
    scale: 1000,
    maxPixels: 1e9
  });

  const vietnamCount = vietnamStats.get('T13').getInfo();

  // Count fire detections in Myanmar
  const myanmarStats = fireMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: myanmar.geometry(),
    scale: 1000,
    maxPixels: 1e9
  });

  const myanmarCount = myanmarStats.get('T13').getInfo();

  console.log('Vietnam fire detections:', vietnamCount);
  console.log('Myanmar fire detections:', myanmarCount);

  // Validate results
  if (vietnamCount === null || myanmarCount === null) {
    console.log('Calculation failed - null values returned');
    console.log('<answer>C3</answer>');
    return;
  }

  if (vietnamCount === 0 && myanmarCount === 0) {
    console.log('No valid fire pixels detected in either country');
    console.log('<answer>C2</answer>');
    return;
  }

  // Compare fire detections
  if (vietnamCount > myanmarCount) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
